import { describe, it, expect } from 'vitest';
import { jsonlStreamConsumer, jsonlStreamProducer } from './jsonl';
import { run } from '../utils';

describe('jsonl regression', () => {
  it('should not abort when one chunk finishes if others are pending', async () => {
    const data = {
      p1: Promise.resolve(1),
      p2: new Promise((resolve) => setTimeout(() => resolve(2), 50)),
    };

    const stream = jsonlStreamProducer({
      data,
    });

    const ac = new AbortController();
    const [head, meta] = await jsonlStreamConsumer<typeof data>({
      from: stream,
      abortController: ac,
    });

    const v1 = await head.p1;
    expect(v1).toBe(1);

    // If the regression exists, ac.signal will be aborted now,
    // and head.p2 will never resolve or will throw AbortError.

    expect(ac.signal.aborted).toBe(false);

    const v2 = await head.p2;
    expect(v2).toBe(2);
    expect(meta.isEmpty()).toBe(true);
  });
});

