describe('jsonl regression', () => {
  it('should not abort when a promise finishes but an async iterable is still pending', async () => {
    const data = {
      p1: Promise.resolve(1),
      i2: (async function* () {
        await new Promise((resolve) => setTimeout(resolve, 50));
        yield 2;
      })(),
    };

    const stream = jsonlStreamProducer({
      data,
    });

    const ac = new AbortController();
    const [head, meta] = await jsonlStreamConsumer<typeof data>({
      from: stream,
      abortController: ac,
    });

    const v1 = await head.p1;
    expect(v1).toBe(1);

    // If the regression exists, ac.signal will be aborted now
    expect(ac.signal.aborted).toBe(false);

    const aggregated: number[] = [];
    for await (const item of head.i2 as any) {
      aggregated.push(item);
    }
    expect(aggregated).toEqual([2]);
    expect(meta.isEmpty()).toBe(true);
  });
});

